11	/**
12	 * Rejects a create request that is missing or blank in any mandatory owner field, before the body
13	 * is mapped to an entity. Publishes the body for {@link BuildOwner} once every field is present.
14	 */
15	public class RequireOwnerFields {
16	
17	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
18	            throws MissingOwnerFieldsException {
19	        List<String> missing = new ArrayList<>();
20	        require("firstName", request.getFirstName(), missing);
21	        require("lastName", request.getLastName(), missing);
22	        require("address", request.getAddress(), missing);
23	        require("city", request.getCity(), missing);
24	        require("telephone", request.getTelephone(), missing);
25	        if (!missing.isEmpty()) {
26	            throw new MissingOwnerFieldsException(missing);
27	        }
28	        validated.set(request);
29	    }
30	
31	    private void require(String name, String value, List<String> missing) {
32	        if (value == null || value.isBlank()) {
33	            missing.add(name);
34	        }
35	    }
36	}
