6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	
8	/**
9	 * Normalises the create request address in place into one canonical form: trimmed, internal
10	 * whitespace collapsed, upper-cased, and common street-type abbreviations expanded (ST-&gt;STREET,
11	 * RD-&gt;ROAD, AVE-&gt;AVENUE). Mutating the published {@link OwnerFieldsDto} means {@link BuildOwner}
12	 * stores the normalised value and every later comparison — household duplicate detection and the
13	 * shared household id — sees it. A null address is left for {@code RequireOwnerFields} to reject.
14	 */
15	public class NormalizeOwnerAddress {
16	
17	    private static final Map<String, String> ABBREVIATIONS =
18	            Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
19	
20	    public void service(@Val OwnerFieldsDto request) {
21	        String address = request.getAddress();
22	        if (address == null) {
23	            return;
24	        }
25	        StringBuilder normalized = new StringBuilder();
26	        for (String token : address.trim().toUpperCase().split("\\s+")) {
27	            if (normalized.length() > 0) {
28	                normalized.append(' ');
29	            }
30	            normalized.append(ABBREVIATIONS.getOrDefault(token, token));
31	        }
32	        request.setAddress(normalized.toString());
33	    }
34	}
